+// Per-column sum: walk row by row so consecutive `c` accesses hit
+// contiguous memory. Each inner-loop iteration reads data_[r * cols_ + c]
+// for the next `c`, which is one double apart and stays inside one cache
+// line for the whole row. The previous column-major version strided by
+// `cols_` doubles per access and blew the L1 cache on large matrices.
+std::vector<double> Matrix::SumPerColumn() const {
+    std::vector<double> result(cols_, 0.0);
+    for (std::size_t r = 0; r < rows_; ++r) {
+        for (std::size_t c = 0; c < cols_; ++c) {
+            result[c] += data_[r * cols_ + c];
+        }
+    }
+    return result;
+}
